import {Avatar} from "@mui/material";
import {GridActionsCellItem, GridColDef, GridRowId, GridRowParams} from "@mui/x-data-grid";
import {NavLink} from "react-router-dom";
import EditTwoToneIcon from "@mui/icons-material/EditTwoTone";
import DeleteTwoToneIcon from "@mui/icons-material/DeleteTwoTone";
import React from "react";
import {Translate} from "../../i18n";

const serviceColumns: (handleSetService: (id: GridRowId) => void, t: Translate) => GridColDef[] = (handleSetService, t) => [
    {
        field: "imageName",
        align: "center",
        headerName: "",
        width: 64,
        renderCell: (params) => (
            <Avatar
                sx={{width: 36, height: 36, borderRadius: "10px"}}
                variant="rounded"
                src={params.value}
                alt={params.row.name}
            />
        ),
    },
    {
        field: "name",
        headerName: t("Name"),
        minWidth: 240,
        flex: 1,
        renderCell: params => <NavLink to={`/servicesManagement/${params.id}`} style={{color: "inherit", textDecoration: "none"}}>{params.value}</NavLink>,
    },
    {
        field: "price",
        headerName: t("Price, BYN"),
        type: "number",
        align: "center",
        width: 130,
    },
    {
        field: "category",
        headerName: t("Category"),
        sortable: true,
        minWidth: 160,
        flex: 0.7,
    },
    {
        field: "Edit",
        headerName: t("Edit"),
        type: "actions",
        width: 92,
        getActions: (params: GridRowParams) => [
            <GridActionsCellItem
                icon={
                    <NavLink
                        style={{textDecoration: "none", color: "inherit"}}
                        to={`/servicesManagement/editService/${params.id}`}
                    >
                        <EditTwoToneIcon/>
                    </NavLink>
                }
                label={t("Edit")}
            />,
        ],
    },
    {
        field: "Delete",
        headerName: t("Delete"),
        type: "actions",
        width: 92,
        getActions: (params: GridRowParams) => [
            <GridActionsCellItem
                icon={<DeleteTwoToneIcon/>}
                label={t("Delete")}
                onClick={() => handleSetService(params.id)}
            />,
        ],
    },
];

export default serviceColumns;
