import {getApiErrorMessage} from "../../api/errors";
import QueryError from "../shared/QueryError";
import React, {useEffect, useState} from "react";
import {Button, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle} from "@mui/material";
import {GridRowId, GridRowSelectionModel} from "@mui/x-data-grid";
import TuneIcon from "@mui/icons-material/Tune";
import AddIcon from "@mui/icons-material/Add";
import SearchIcon from "@mui/icons-material/Search";
import ClearIcon from "@mui/icons-material/Clear";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import {NavLink} from "react-router-dom";
import styledCom from "styled-components";
import Loader from "../../ui/loader/loader";
import CoreButton from "../../ui/buttons/coreButton";
import CoreTextField from "../../ui/textFields/coreTextField";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
    Toolbar,
    ToolbarActions,
} from "../../ui/commonStyled/commonStyled";
import useDebounce from "../../hooks/useDebounce";
import {ServiceParams} from "../../models/service";
import {
    useBulkDeleteServicesMutation,
    useDeleteServiceMutation,
    useGetServicesQuery,
} from "./servicesApi";
import serviceColumns from "./serviceColumns";
import {useTranslation} from "../../i18n";
import BulkDeleteDialog from "../shared/bulkDelete/BulkDeleteDialog";
import {toast} from "react-toastify";

const SearchLabel = styledCom.div({
    display: "flex",
    alignItems: "center",
    gap: "8px",
    color: "var(--color-muted)",
    fontSize: "13px",
    fontWeight: 760,
});

const initialServiceParams: ServiceParams = {
    pageNumber: 1,
    pageSize: 15,
    categories: [],
    searchTerm: "",
};

const ServicesManagement = () => {
    const {t} = useTranslation();
    const [serviceParams, setServiceParams] = useState<ServiceParams>(initialServiceParams);
    const {data, isLoading, isFetching, isError, error, refetch} = useGetServicesQuery(serviceParams);
    const [deleteService, {isLoading: isDeleting}] = useDeleteServiceMutation({});
    const [bulkDeleteServices, {isLoading: isBulkDeleting}] = useBulkDeleteServicesMutation();

    const [searchTerm, setSearchTerm] = useState("");
    const debouncedSearch = useDebounce(searchTerm);

    const [deleteWindowOpen, setDeleteWindowOpen] = useState(false);
    const [deletedId, setDeletedId] = useState<GridRowId>("");
    const [selectedIds, setSelectedIds] = useState<GridRowSelectionModel>([]);
    const [bulkDeleteOpen, setBulkDeleteOpen] = useState(false);

    const handleSetService = (id: GridRowId) => {
        setDeleteWindowOpen(true);
        setDeletedId(id);
    };

    async function deleteServiceHandler() {
        try {
            await deleteService(deletedId).unwrap();
            toast.success(t("Услуга удалена."));
            setSelectedIds((current) => current.filter((id) => id !== deletedId));
            setDeleteWindowOpen(false);
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось удалить запись.")));
        }
    }

    useEffect(() => {
        setServiceParams((current) => ({...current, searchTerm: debouncedSearch}));
    }, [debouncedSearch]);

    const pageChangeHandler = (e: any) => {
        setServiceParams((current) => ({
            ...current,
            pageNumber: e.page,
            pageSize: e.pageSize,
        }));
    };

    const bulkDeleteHandler = async () => {
        try {
            const result = await bulkDeleteServices({ids: selectedIds.map(Number)}).unwrap();
            setSelectedIds([]);
            setBulkDeleteOpen(false);
            toast.success(t("Deleted items: {count}", {count: result.deleted}));
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось удалить запись.")));
        }
    };

    if (isLoading && !searchTerm) {
        return <Loader/>;
    }

    if (isError) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;

    return (
        <MainDiv>
            <BulkDeleteDialog
                open={bulkDeleteOpen}
                selectedCount={selectedIds.length}
                isLoading={isBulkDeleting}
                onClose={() => setBulkDeleteOpen(false)}
                onConfirm={bulkDeleteHandler}
            />
            <Dialog
                open={deleteWindowOpen}
                onClose={() => {if (!isDeleting) setDeleteWindowOpen(false);}}
            >
                <DialogTitle>{t("Confirm service deletion")}</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        {t("Do you really want to delete this service from the system?")}
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button disabled={isDeleting} onClick={() => setDeleteWindowOpen(false)}>{t("Cancel")}</Button>
                    <Button color="error" disabled={isDeleting} onClick={() => void deleteServiceHandler()} autoFocus>
                        {t("Delete")}
                    </Button>
                </DialogActions>
            </Dialog>

            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Services")}</PageTitle>
                    <PageSubtitle>
                        {t("Service catalog with prices, categories, and quick search.")}
                    </PageSubtitle>
                </PageTitleGroup>
                <NavLink to="createService" style={{textDecoration: "none"}}>
                    <CoreButton
                        muiType="success"
                        text={t("Add service")}
                        leftIcon={<AddIcon/>}
                    />
                </NavLink>
            </PageHeader>

            <Surface>
                <Toolbar>
                    <SearchLabel>
                        <SearchIcon fontSize="small"/>
                        {t("Service search")}
                    </SearchLabel>
                    <ToolbarActions>
                        {selectedIds.length > 0 && (
                            <CoreButton
                                muiType="secondary"
                                text={t("Clear selection")}
                                leftIcon={<ClearIcon/>}
                                onClick={() => setSelectedIds([])}
                            />
                        )}
                        <CoreButton
                            muiType="error"
                            text={t("Delete selected ({count})", {count: selectedIds.length})}
                            leftIcon={<DeleteOutlineIcon/>}
                            disabled={selectedIds.length === 0 || isBulkDeleting}
                            onClick={() => setBulkDeleteOpen(true)}
                        />
                        <CoreButton
                            text={t("Filters")}
                            leftIcon={<TuneIcon/>}
                        />
                    </ToolbarActions>
                </Toolbar>
                <CoreTextField
                    verticalMargin
                    value={searchTerm || ""}
                    label={t("Service name or description...")}
                    onChange={(e: any) => {
                        setSearchTerm(e.target.value);
                    }}
                />
                <StyledDataGrid
                    pagination
                    paginationMode="server"
                    rowCount={data?.metaData.totalCount ?? 0}
                    autoHeight
                    rows={data?.items ?? []}
                    columns={serviceColumns(handleSetService, t)}
                    loading={isLoading || isFetching}
                    onPaginationModelChange={(e) => pageChangeHandler(e)}
                    pageSizeOptions={[25, 50, 100]}
                    disableRowSelectionOnClick
                    checkboxSelection
                    keepNonExistentRowsSelected
                    rowSelectionModel={selectedIds}
                    onRowSelectionModelChange={setSelectedIds}
                />
            </Surface>
        </MainDiv>
    );
};

export default ServicesManagement;
