import React from 'react';
import {MyButton} from "./styled";

interface CoreButtonProps {
    onClick?: any;
    leftIcon?: any;
    rightIcon?: any;
    text?: string;
    muiType?: 'primary' | 'secondary' | 'success' | 'edit' | 'info' | 'error';
    type?: 'submit' | 'reset' | 'button';
    fullWidth?: boolean;
    horizontalMargin?: boolean;
    verticalMargin?: boolean;
    bottomMargin?:boolean;
    disabled?: boolean;
    ariaLabel?: string;
}

const CoreButton = ({
                        fullWidth,
                        type,
                        onClick,
                        leftIcon,
                        rightIcon,
                        text,
                        muiType,
                        horizontalMargin,
                        verticalMargin,
                        bottomMargin,
                        disabled,
                        ariaLabel,
                    }: CoreButtonProps) => {
    return (
        <MyButton
            fullWidth={fullWidth}
            type={type}
            muiType={muiType}
            startIcon={leftIcon}
            endIcon={rightIcon}
            onClick={onClick}
            verticalMargin={verticalMargin ? verticalMargin : false}
            horizontalMargin={horizontalMargin ? horizontalMargin : false}
            bottomMargin={bottomMargin ? bottomMargin : false}
            disabled={disabled}
            aria-label={ariaLabel}
        >
            {text}
        </MyButton>
    );
};

export default CoreButton;
